const qzData=[{"q":"Según Melanie Green y Timothy Brock (2000), ¿qué mide el transporte narrativo?","o":["a) Cuántas lágrimas produce una escena","b) Cuánto se absorbe el lector en el relato, y cómo eso baja sus defensas","c) La duración exacta de una historia","d) El presupuesto de un video"],"c":1,"e":"El transporte narrativo mide la absorción autoinformada del lector: cuanto más transportado, más se conmueve y menos defensa crítica opone."},{"q":"Según Aristóteles, en su «Poética» (hacia el 335 a.C.), ¿de dónde sale la emoción de la tragedia?","o":["a) De música que hincha la escena","b) De la estructura: el error del héroe, el reconocimiento, la peripecia","c) De mostrar la mayor cantidad de sangre posible","d) De repetir el mismo giro varias veces"],"c":1,"e":"La catarsis, la purga de la piedad y el temor, se gana con la estructura de la tragedia, no con botones sueltos."},{"q":"¿Cómo define James Baldwin, en «Everybody's Protest Novel» (1949), el sentimentalismo?","o":["a) Como la exhibición ostentosa de una emoción excesiva y espuria","b) Como cualquier historia que hace llorar","c) Como un recurso siempre válido en la novela social","d) Como sinónimo de compasión"],"c":0,"e":"Baldwin llama al sentimentalismo la marca de la deshonestidad: una emoción exhibida de más, espuria."},{"q":"Según Flannery O'Connor, «Mystery and Manners» (1969), ¿qué es la sentimentalidad?","o":["a) La única forma honesta de emocionar","b) Un invento moderno del cine","c) Un atajo que se salta el proceso que la emoción tenía que recorrer","d) Lo mismo que el suspense"],"c":2,"e":"O'Connor la describe como una llegada demasiado temprana a una inocencia fingida, un atajo."},{"q":"¿Qué encontraron Deborah Small, George Loewenstein y Paul Slovic (2007) sobre la donación?","o":["a) Que la gente da MENOS cuando se le muestran las cifras junto al caso de una persona","b) Que una estadística recauda siempre más que una persona con nombre","c) Que las cifras nunca afectan la donación","d) Que mostrar una foto nunca cambia nada"],"c":0,"e":"El efecto de la víctima identificable: una persona con nombre y cara recauda más, y las cifras junto al caso, en vez de sumar, restan."},{"q":"Según Susan Sontag, «Ante el dolor de los demás» (2003), ¿qué NO es estar conmovido por una imagen de sufrimiento?","o":["a) Un sentimiento real","b) Lo mismo que entenderlo o que hacer algo","c) Algo que se pueda fabricar","d) Algo que se pueda agotar"],"c":1,"e":"Sontag distingue estar conmovido de comprender o de actuar: la compasión se puede fabricar y agotar."},{"q":"¿Cuáles son las tres casillas de la cuenta de la emoción, la herramienta de esta etapa?","o":["a) ¿Está ganada?, ¿es proporcionada?, ¿respeta al que la siente?","b) Título, música y duración","c) Presupuesto, elenco y locación","d) Suspense, curiosidad y sorpresa"],"c":0,"e":"La cuenta de la emoción tiene tres casillas: si la emoción está ganada, si es proporcionada, y si respeta al que la siente."},{"q":"¿Qué es el entumecimiento psíquico (psychic numbing), según Paul Slovic (2007)?","o":["a) Que las estadísticas siempre conmueven más que una persona","b) Un tipo de música que se usa en documentales","c) La cura para el sentimentalismo","d) Que cuantas más personas mueren, menos nos importa"],"c":3,"e":"El entumecimiento psíquico: la escala grande de sufrimiento (muchas muertes) nos afecta menos que una sola persona con nombre."},{"q":"¿Qué estatus tiene la afirmación «las historias liberan oxitocina y por eso nos hacen empáticos» (Paul Zak, hacia 2013)?","o":["a) Hallazgo replicado con corpus amplio","b) Ley biológica comprobada","c) Divulgación inflada: estudios pequeños, mecanismo sobrevendido","d) Concepto clásico de la retórica"],"c":2,"e":"La oxitocina de las historias es la pseudorregla que esta etapa desinfla: divulgación inflada, no un hecho firme."},{"q":"¿Cuál es el freno de la casa contra el chantaje emocional?","o":["a) Que la historia nunca use ninguna cifra","b) Que la música siempre acompañe la emoción","c) Que se repita la misma escena tres veces","d) Que la historia aguante que después se muestre el dato o la letra pequeña"],"c":3,"e":"El freno: la historia arriba, la cifra completa debajo, nunca en un anexo. Si no aguanta el dato, es chantaje."}];
let qzIdx=0,qzSel=-1,qzDone=false;
