const explainQuestions=[{"q":"Explica el transporte narrativo, según Melanie Green y Timothy Brock (2000), y su límite.","ans":"Melanie Green y Timothy Brock, en «The role of transportation in the persuasiveness of public narratives» (2000), describen el transporte narrativo: el mecanismo medido por el que un relato absorbe al lector y baja sus defensas críticas; cuanto más transportado, más se conmueve. Su límite es central para esta etapa: el transporte mide la absorción autoinformada, pero por sí solo NO distingue la emoción ganada de la manipulada, solo mide cuánto absorbe, sin decir si ese efecto se ganó con honradez."},{"q":"Explica la catarsis, según Aristóteles, «Poética» (hacia el 335 a.C.), y por qué su definición sigue discutida.","ans":"Aristóteles, en su «Poética» (hacia el 335 a.C.), sostiene que la emoción de la tragedia, la piedad y el temor, se gana con la estructura: el error del héroe, el reconocimiento, la peripecia, no con botones sueltos. La catarsis es esa purga. Su límite es que el propio Aristóteles apenas define el término, y lleva siglos de discusión filosófica sobre qué quiso decir exactamente."},{"q":"Explica la diferencia entre el sentimentalismo como deshonestidad, de James Baldwin (1949), y como atajo, de Flannery O'Connor (1969).","ans":"James Baldwin, en «Everybody's Protest Novel» (1949), define el sentimentalismo como la exhibición ostentosa de una emoción excesiva y espuria, marca de la incapacidad de sentir de verdad: una deshonestidad. Flannery O'Connor, en «Mystery and Manners» (1969), lo describe como un atajo: una llegada demasiado temprana a una inocencia fingida, que se salta el proceso que la emoción tenía que recorrer para ser verdadera. Las dos coinciden en que la sentimentalidad es un fallo técnico, no solo moral, aunque Baldwin acentúa la deshonestidad y O'Connor el atajo de oficio."},{"q":"Explica el efecto de la víctima identificable, de Deborah Small, George Loewenstein y Paul Slovic (2007), y su límite.","ans":"Deborah Small, George Loewenstein y Paul Slovic, en 2007, muestran que una persona con nombre y cara recauda más que una estadística, y que la gente da MENOS cuando se le muestran las cifras junto al caso de esa persona. Es el mecanismo real de la manipulación emocional en la donación, el dato más usado y peor usado del sector. Su límite: es un hallazgo de laboratorio, y se profundiza en la Ruta del Expediente Real (etapa 6 de esa ruta)."},{"q":"Explica por qué la afirmación «las historias liberan oxitocina y por eso nos hacen empáticos» (Paul Zak, hacia 2013) lleva la etiqueta de divulgación inflada.","ans":"La idea popular de que «las historias liberan oxitocina y por eso nos hacen empáticos», atribuida a Paul Zak hacia 2013, se apoya en estudios pequeños y en un mecanismo sobrevendido en charlas y artículos de divulgación; la investigación con oxitocina en humanos es, además, de las más difíciles de replicar. Por eso lleva la etiqueta de divulgación inflada: la lección de esta etapa es que el relato conmueve de verdad, como mide el transporte narrativo de Green y Brock (2000), pero «te llena de oxitocina» es un titular, no un hecho firme."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> Una persona con nombre y cara recauda más que una estadística. → <span style="color:var(--jade);font-weight:700;">El efecto de la víctima identificable (Small, Loewenstein y Slovic, 2007)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

