function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"LA FOTO QUE ESCONDE EL DATO EN UN ANEXO. Una convocatoria de becas de L 180,000 abre su video con la foto de un niño llorando, y solo hasta el anexo, en letra pequeña, explica cómo se reparte el dinero entre los postulantes."},{"txt":"LA ESCENA GANADA QUE AGUANTA LA TABLA. Un video de un proyecto de huertos de L 220,000 muestra una escena real y concreta, una madre que por fin cosecha su propia comida, y cierra mostrando la tabla completa de gastos, sin esconder nada."},{"txt":"EL TESTIMONIO INFLADO CON ADJETIVOS. Un testimonio de una beca de L 45,000 lo describe todo como «desgarrador», «milagroso» y «sin precedentes», sin mostrar una sola escena concreta de lo que de verdad pasó."},{"txt":"LA MÚSICA QUE HINCHA UNA ESCENA QUE NO GIRA. Un video de una feria de M.E.T.A.S de L 60,000 pone música de piano y cámara lenta sobre una escena de rutina, donde nada cambia ni se decide."},{"txt":"LA CIFRA GRANDE QUE NO CONMUEVE A NADIE. Un informe anuncia que el proyecto benefició a 3,200 familias con L 900,000, y nadie en la sala reacciona a la cifra."},{"txt":"EL CIERRE SECO QUE CONMUEVE MÁS QUE EL LLANTO. Un informe de un programa de lectura de L 130,000 cierra con una sola frase objetiva, sin un solo adjetivo, y conmueve más que los tres párrafos llorosos que lo preceden."},{"txt":"LA OXITOCINA EN EL INFORME. Un informe de M.E.T.A.S de L 75,000 afirma, como si fuera un dato comprobado, que «este video llena de oxitocina a quien lo ve» y por eso «funciona mejor que cualquier otro»."},{"txt":"LA ESCENA GANADA FRENTE AL BOTÓN QUE NO GIRA. Un video de una graduación de L 100,000 compara dos finales posibles: uno con música que hincha sin que nada cambie, y otro con el silencio de una madre que ve el diploma de su hijo por primera vez."}];
const critCaseQuestions=["1. Di si el problema de este caso está en que la emoción NO ESTÁ GANADA, NO ES PROPORCIONADA, o NO RESPETA al que la siente, y por qué.","2. Aplica la cuenta de la emoción completa: ¿está ganada?, ¿es proporcionada?, ¿respeta al que la siente?","3. Aplica una herramienta de la etapa (Green y Brock 2000, Aristóteles hacia el 335 a.C., Baldwin 1949, O'Connor 1969, Small, Loewenstein y Slovic 2007, o Sontag 2003) con su autor y su año.","4. Escribe la pregunta que decide y la condición con la que el caso quedaría resuelto."];
const critCaseGuides=["Se valora que se identifique con claridad de cuál de las tres casillas viene el problema real del caso, sin mezclar las tres en una sola respuesta vaga.","Se valora que las tres casillas queden llenas con algo concreto del caso, o con la nota honesta de que alguna todavía no se puede llenar.","Se valora que la herramienta elegida encaje con el problema real del caso (una foto que esconde el dato pide a Small, Loewenstein y Slovic; un testimonio inflado con adjetivos pide a Baldwin y a O'Connor; una escena ganada pide al transporte de Green y Brock) y que viaje con su autor y su año.","Se valora que la pregunta que decide sea concreta y que la condición diga con claridad qué cambiaría para que el caso quedara resuelto. No se valora cerrar con «hay que emocionar más», que es justo la frase que este caso desmiente."];
const critErrorBank=[{"txt":"«Hay que hacer llorar siempre al público, así se sabe que el video funciona»","g1":"Confunde estar conmovido con haber entendido algo, o con que la historia sea buena: más lágrimas no es sinónimo de mejor historia (Baldwin, 1949).","g2":"No distingue la emoción ganada, la que sale de algo que el relato construyó, del sentimentalismo, la emoción pedida sin haberla ganado."},{"txt":"«El chantaje emocional es cualquier historia que usa la foto de una persona real»","g1":"Confunde usar una imagen con manipular: el efecto de la víctima identificable (Small, Loewenstein y Slovic, 2007) no prohíbe la foto, exige que aguante mostrar el dato completo después.","g2":"No aplica el freno de la casa: si la historia aguanta que se enseñe la cifra completa, no es chantaje, sea cual sea la imagen que use."},{"txt":"«La catarsis es un término que Aristóteles definió con precisión matemática»","g1":"Le atribuye a Aristóteles (hacia el 335 a.C.) una precisión que su propio texto no tiene: la catarsis apenas se define en la «Poética», y lleva siglos discutida.","g2":"No distingue la catarsis, ganada por la estructura de la tragedia, de un llanto cualquiera sin esa estructura detrás."},{"txt":"«Mostrar la cifra completa junto a la historia le quita fuerza emocional al relato»","g1":"Invierte el freno de la casa: la historia arriba y la cifra completa debajo no le quita fuerza al relato, es la prueba de que la emoción se ganó de verdad (Sontag, 2003).","g2":"No distingue el chantaje (esconder el dato) de la honradez (mostrarlo y que la historia lo aguante)."},{"txt":"«Las historias liberan oxitocina, así que cualquier historia mejora la empatía de quien la ve»","g1":"Repite la divulgación inflada de Paul Zak (hacia 2013) sin su etiqueta: son estudios pequeños, sobrevendidos, y la investigación con oxitocina en humanos es de las más difíciles de replicar.","g2":"No distingue el transporte narrativo (Green y Brock, 2000), un hallazgo medido, de la afirmación sobre la oxitocina, que no lo es."},{"txt":"«El sentimentalismo es sentir demasiado, y eso siempre es un defecto que hay que evitar por completo»","g1":"Confunde sentir mucho con el sentimentalismo, que es un exceso ESPURIO, no cualquier emoción intensa ganada de verdad por una escena.","g2":"No distingue la emoción proporcionada, ganada y a la altura de lo que pasó, del sentimentalismo, que es la que no cabe en lo que de verdad ocurrió."}];
const critDecisionBank=["La convocatoria de becas de L 180,000 ya abrió su video con la foto de un niño llorando, y el dato del reparto sigue en el anexo: ¿se mueve el dato a la pantalla principal, se deja en el anexo porque «ya está», o se quita la foto por completo? Di qué harías.","El video de huertos de L 220,000 ya muestra la escena ganada y la tabla de gastos: ¿se deja como está, se le añade más música para «reforzar» la emoción, o se recorta la tabla porque «ya emocionó bastante»? Di el efecto de cada opción.","El testimonio de L 45,000 ya está lleno de adjetivos («desgarrador», «milagroso»): ¿se reescribe mostrando una escena concreta, se deja porque «así se siente más fuerte», o se le agregan más adjetivos todavía? Di qué se pierde con cada opción.","El video de la feria de L 60,000 ya tiene música de piano sobre una escena que no gira: ¿se quita la música y se deja la escena en silencio, se busca una escena que sí gire, o se sube el volumen de la música «para que se note más»? Di tu decisión.","El informe ya anuncia 3,200 familias beneficiadas con L 900,000, sin que nadie reaccione: ¿se cuenta con una sola familia concreta, sin esconder la cifra completa, se deja la cifra sola porque «es la que importa», o se agregan más cifras todavía? Di la condición con la que sí lo dejarías.","El informe del programa de lectura de L 130,000 ya cierra con una frase seca y objetiva: ¿se deja así, se le agregan adjetivos «para emocionar más», o se pide feedback a un grupo de prueba? Di qué harías.","El informe de M.E.T.A.S de L 75,000 ya afirma que el video «llena de oxitocina» a quien lo ve: ¿se quita la afirmación y se cita el transporte narrativo (Green y Brock, 2000) en su lugar, se deja porque «suena convincente», o se agrega una cifra inventada para reforzarla? Di el riesgo de cada opción.","El video de graduación de L 100,000 tiene dos finales posibles, uno con música que hincha y otro con el silencio de una madre: ¿se elige el silencio, se combinan los dos, o se elige la música porque «es más segura»? Di con qué protocolo lo decidirías."];
const critDecisionGuide="La decisión se puntúa por el procedimiento con que se llegó a ella, no por lo audaz que suene. Se valora que se identifique si el problema real está en que la emoción no está ganada, no es proporcionada, o no respeta al que la siente, y que la herramienta elegida (Green y Brock, Aristóteles, Baldwin, O'Connor, Small, Loewenstein y Slovic, o Sontag) encaje con el problema real y viaje con su autor y su año. Se valora que la respuesta no se cierre con «así se emociona más» ni con «hay que hacer llorar siempre», que son las dos fórmulas que esta etapa sustituye. Se valora la honradez cuando el caso, tal como está descrito, no permite decidir con los datos que hay: decir «falta este dato» es una respuesta correcta.";
const critCompareBank=[{"a":"«El video de la convocatoria abre con la foto de un niño llorando, y el reparto del dinero queda en un anexo, en letra pequeña.»","b":"«El video de la convocatoria abre con la misma foto, y en la siguiente escena muestra, con toda claridad, cómo se reparte el dinero entre los postulantes.»","ga":"Esconde el dato detrás de la imagen: no aguanta el freno de la casa, y por eso es un caso de chantaje emocional (Small, Loewenstein y Slovic, 2007).","gb":"Aplica el freno de la casa: la historia arriba, el dato completo debajo, a la vista, sin esconderlo en ningún anexo.","gr":"Los dos videos usan la misma imagen. La diferencia es si el dato se enseña o se esconde, que es justo la línea entre conmover y manipular."},{"a":"«El testimonio describe todo como desgarrador, milagroso y sin precedentes, sin mostrar ninguna escena concreta.»","b":"«El testimonio muestra una sola escena concreta: la primera vez que la alumna leyó un libro completo sola, sin ningún adjetivo alrededor.»","ga":"Es sentimentalismo, según Baldwin (1949): la exhibición ostentosa de una emoción excesiva y espuria, sin nada concreto detrás que la sostenga.","gb":"Es emoción ganada: la escena concreta hace el trabajo que los adjetivos solo fingen hacer.","gr":"Los dos testimonios hablan de la misma alumna. La diferencia es si la emoción se pide con adjetivos o se gana con un hecho concreto."},{"a":"«El informe anuncia 900,000 lempiras y 3,200 familias beneficiadas, y nadie en la sala reacciona.»","b":"«El informe cuenta la historia de una sola familia, con su nombre, y termina mostrando que esa familia es una de las 3,200 que la cifra completa reporta.»","ga":"Sufre el entumecimiento psíquico (Slovic, 2007): la cifra grande no conmueve a nadie, aunque sea real.","gb":"Usa el efecto de la víctima identificable (Small, Loewenstein y Slovic, 2007) sin esconder la cifra: abre camino al dato, en vez de taparlo.","gr":"Los dos informes hablan del mismo proyecto. La diferencia es si la cifra se cuenta sola, o se cuenta con una persona que la haga sentir real, sin esconderla."},{"a":"«El informe afirma que el video llena de oxitocina a quien lo ve, y por eso funciona mejor que cualquier otro.»","b":"«El informe dice que el video transporta al espectador, y cita el estudio de Green y Brock (2000) sobre el transporte narrativo.»","ga":"Repite una divulgación inflada (Zak, hacia 2013): estudios pequeños, sobrevendidos, sin corpus firme detrás.","gb":"Cita un hallazgo medido y replicado (Green y Brock, 2000), con su autor y su año, en vez de un titular.","gr":"Los dos informes hablan del mismo efecto, que el video conmueve. La diferencia es si la explicación se apoya en ciencia inflada o en ciencia medida."}];
const critCauseBank=[{"cause":"Un video abre con la foto de un niño llorando y esconde el reparto del dinero en un anexo.","guide":"Es un caso de chantaje emocional: no aguanta el freno de la casa. Se corrige moviendo el dato a la pantalla principal, junto a la historia (Small, Loewenstein y Slovic, 2007)."},{"cause":"Un testimonio se llena de adjetivos («desgarrador», «milagroso») sin mostrar ninguna escena concreta.","guide":"Es sentimentalismo (Baldwin, 1949): una emoción exhibida sin haberla ganado. Se corrige mostrando el hecho concreto, y dejando que la escena haga el trabajo."},{"cause":"Una música de piano hincha una escena en la que nada cambia ni se decide.","guide":"Es emoción pedida sin ganar: la música intenta compensar lo que la escena no construyó. Se corrige quitando la música, o buscando una escena que sí gire."},{"cause":"Un informe anuncia una cifra grande de beneficiarios, y nadie reacciona.","guide":"Es el entumecimiento psíquico (Slovic, 2007): la escala grande no conmueve. Se corrige contando con una persona concreta, sin esconder la cifra completa."},{"cause":"Un informe afirma, sin más, que un video «llena de oxitocina» a quien lo ve.","guide":"Es divulgación inflada (Zak, hacia 2013). Se corrige citando el transporte narrativo (Green y Brock, 2000), un hallazgo medido, en vez de un titular."},{"cause":"Un video de graduación usa música que hincha una escena donde nada cambia, en vez del silencio de una madre viendo el diploma.","guide":"Confunde volumen emocional con emoción ganada: la escena silenciosa y concreta conmueve más porque está construida, no apuntalada con música."}];
const critEffectBank=[{"effect":"El video de la convocatoria muestra el reparto del dinero en la misma escena donde aparece la foto del niño, sin esconder nada.","guide":"Se aplicó el freno de la casa: la historia y el dato conviven, y el video deja de ser chantaje para ser una historia que aguanta el dato."},{"effect":"El testimonio reemplaza los adjetivos por una sola escena concreta y real.","guide":"Se pasó del sentimentalismo a la emoción ganada (Baldwin, 1949; O'Connor, 1969): la escena hace el trabajo que los adjetivos solo fingían hacer."},{"effect":"El video de la feria queda con la escena en silencio, sin música que la hinche.","guide":"Se dejó de pedir una emoción que la escena no había ganado, y se evitó el sentimentalismo como atajo (O'Connor, 1969)."},{"effect":"El informe cuenta la historia de una familia concreta, y muestra que es una de las 3,200 que la cifra completa reporta.","guide":"Se usó el efecto de la víctima identificable (Small, Loewenstein y Slovic, 2007) para abrir camino al dato, no para taparlo."},{"effect":"El informe cita el transporte narrativo (Green y Brock, 2000) en vez de la afirmación sobre la oxitocina.","guide":"Se reemplazó una divulgación inflada por un hallazgo medido y con su año, tal como exige la regla de oro de la materia."},{"effect":"El video de graduación elige el silencio de la madre viendo el diploma, en vez de la música que hinchaba la escena.","guide":"Se eligió la emoción ganada por lo concreto (Aristóteles: la estructura, no los botones) sobre el sentimentalismo pedido con música."}];
function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`💧 La cuenta de la emoción bajo presión · Forma ${cf} · Emoción sin chantaje · Ruta del Hilo que Tira`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El caso sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">Aplica la cuenta de la emoción a este caso: ¿está ganada?, ¿es proporcionada?, ¿respeta al que la siente?, y qué herramienta (con su autor y su año) usarías.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>💧 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La cuenta de la emoción bajo presión: '+total+'/100');}
  else showToast('💧 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
