const lectAnalisisBank=[
{q:'Explica por qué la fotografía de doña Herminia conmueve a Ibarra sin necesidad de la máquina, y relaciona tu respuesta con la distinción de James Baldwin (1949) entre emoción ganada y sentimentalismo.',guia:'Se espera que el lector explique que la fotografía no fue pedida ni fabricada: es un detalle concreto, ganado por una vida entera junto a un río, y por eso llega sin aviso y sin manivela, a diferencia de las lágrimas que la máquina producía a voluntad. Según James Baldwin (1949), el sentimentalismo es la exhibición ostentosa de una emoción excesiva y espuria, la marca de quien no sabe sentir de verdad; las once mil lágrimas fabricadas por Ibarra encajan en esa definición, porque son gesto sin proceso. La fotografía, en cambio, es el ejemplo opuesto: una emoción ganada, que no necesita ostentación porque tiene detrás una causa real y concreta que la sostiene.',t:'Borges'},
{q:'Explica qué relación establece el cuento entre la máquina de fabricar lágrimas y el concepto de transporte narrativo, de Melanie Green y Timothy Brock (2000).',guia:'Se espera que el lector explique que la máquina de Ibarra produce el efecto físico del llanto (el agua, el temblor, el hipo) sin producir el mecanismo que Green y Brock (2000) describen: el transporte narrativo, la absorción que un relato bien construido logra en quien lo escucha. La máquina imita el síntoma sin la causa, mientras que la fotografía de doña Herminia sí transporta a Ibarra de verdad, porque está anclada a una historia real (ella enseñando a pescar a su hijo) que él reconstruye por su cuenta. El cuento ilustra así que producir lágrimas no es lo mismo que transportar a alguien: se puede fabricar el gesto sin ganar la absorción.',t:'Borges'},
{q:'Explica cómo detecta Baltasar Quiroga que Cebrián Otazu está manipulando con su desgracia, y qué detalles concretos lo delatan.',guia:'Se espera que el lector explique que Baltasar detecta la manipulación por dos señales concretas: primero, que Cebrián llora siempre con el mismo gesto mecánico, el ojo izquierdo primero, como si el llanto fuera un truco ensayado y no una reacción espontánea; segundo, que la historia de la desgracia cambia de una versión a otra, ganando o perdiendo hijos y hasta el perro según a quién se la cuenta, lo que revela que no describe un hecho fijo sino una herramienta que se ajusta al público. La escena final, donde Baltasar sorprende a Cebrián ensayando el temblor de la barbilla frente al abrevadero, confirma con los propios ojos lo que las inconsistencias ya delataban: que el dolor se estaba fabricando, no relatando.',t:'Cervantes'},
{q:'Explica por qué el trato final que Baltasar le ofrece a Cebrián no es un castigo sino una salida honrada, y qué dice eso sobre el chantaje emocional.',guia:'Se espera que el lector explique que Baltasar no expone a Cebrián ante los demás huéspedes ni lo denuncia al alguacil, sino que le ofrece, en privado, contar su desgracia real (la mitad que de veras sufrió) a cambio de comer con los mozos de la cocina, no de vivir de la lástima de los mercaderes. Esa salida distingue con cuidado dos cosas que suelen confundirse: castigar a la persona que manipuló, y desarmar la manipulación misma. El capítulo sugiere que la respuesta honesta al chantaje emocional no es la humillación pública, sino cerrarle la puerta al atajo (la lástima que paga sin comprobar nada) mientras se deja abierta la puerta a contar la verdad, que en el capítulo termina siendo, además, más sostenible que la mentira.',t:'Cervantes'},
{q:'Explica la paradoja de la ficción, de Colin Radford (1975), tal como la plantea el ensayo, y cómo se relaciona con el entumecimiento psíquico, de Paul Slovic (2007).',guia:'Se espera que el lector explique que Colin Radford, en 1975, formuló la pregunta de por qué nos conmovemos por el destino de un personaje, como Anna Karenina, sabiendo con toda certeza que nunca existió: no hay engaño posible, y aun así el llanto llega, lo que convierte la emoción de ficción en un enigma filosófico real. El ensayo conecta esa paradoja con el hallazgo de Paul Slovic (2007) sobre el entumecimiento psíquico, la idea de que cuantas más personas sufren, menos nos importa cada una: la misma especie capaz de llorar por una persona de papel puede quedar fría ante una cifra real de sufrimiento humano, y esa asimetría, lejos de ser dos fenómenos separados, es la misma maquinaria emocional vista desde dos ángulos distintos.',t:'Harari'},
{q:'Explica por qué el ensayo etiqueta la afirmación de Paul Zak sobre la oxitocina como divulgación inflada, y qué evidencia da para sostenerlo.',guia:'Se espera que el lector explique que el ensayo no niega que las historias conmuevan, sino que cuestiona la explicación popularizada por Paul Zak hacia 2013, según la cual las historias liberan oxitocina y por eso nos vuelven más empáticos. El ensayo da dos razones para la etiqueta de divulgación inflada: que esa afirmación se apoya en estudios pequeños, difíciles de replicar, y que la investigación con oxitocina en humanos está entre las más resbaladizas de toda la neurociencia. La lección que el ensayo deja es que el mecanismo medido de verdad, el transporte narrativo de Green y Brock (2000), es distinto del titular fácil de repetir en una charla, y que confundir uno con otro es exactamente el tipo de pseudorregla que esta etapa enseña a desinflar.',t:'Harari'},
{q:'Explica la concesión que hace Baldwin sobre el riesgo de su propia dureza frente a la emoción, y por qué esa concesión es importante para entender su postura completa.',guia:'Se espera que el lector explique que, después de defender con firmeza que el sentimentalismo es una deshonestidad, Baldwin acepta la objeción de Soler Serrano de que esa misma dureza puede volverse su propio problema: la desconfianza de la emoción puede convertirse en frialdad, una pose de dureza tan falsa como la lágrima que él mismo criticaba. Baldwin llega a decir que ha visto críticos que presumen de no conmoverse nunca, y que esa presunción es tan hueca como el sentimentalismo que ataca. Esta concesión es importante porque evita que la postura de Baldwin se lea como «nunca hay que sentir»: el peligro, aclara él mismo, nunca fue sentir, sino sentir de mentira, ya sea llorando de más o negándose a llorar por orgullo.',t:'Entrevista'},
{q:'Explica la diferencia que Baldwin traza entre una emoción ganada y una emoción exhibida, con el ejemplo que usa en la entrevista.',guia:'Se espera que el lector explique que, para Baldwin, la emoción ganada cuesta algo: exige mirar de frente lo que preferiríamos no mirar, mientras que el sentimentalismo toma el gesto del dolor (la lágrima, el suspiro) sin haber pagado el precio de entenderlo de verdad. Baldwin lo aterriza con la prueba de la pregunta de por qué: si alguien puede explicar, sin vergüenza, qué escena o qué detalle concreto le costó una lágrima, la emoción está ganada; si la única respuesta posible es «así se siente», entonces a esa persona le vendieron el lujo de una emoción sin que la haya pagado, que es justo la frase que titula esta lectura.',t:'Entrevista'},
{q:'Explica la técnica objetivista de Rafael Sánchez Ferlosio en «El Jarama» (1955), y por qué él mismo dice que tachaba páginas donde le decía al lector qué sentir.',guia:'Se espera que el lector explique que Sánchez Ferlosio construye «El Jarama» sin adjetivos que empujen al lector hacia una emoción concreta: la gente habla, se baña y juega a las cartas, y cuando alguien se ahoga al final, el narrador no añade ninguna palabra de más a esa muerte. Según cuenta en la conversación, él mismo tachaba páginas enteras cuando se sorprendía indicándole al lector qué sentir, porque temía lo contrario de lo que muchos temen: no que el lector sintiera poco sin ayuda, sino que sintiera exactamente lo que el autor le hubiera ordenado sentir, en vez de lo que la escena, dejada en paz, le daría por su propia cuenta.',t:'Quintero y Sánchez Ferlosio'},
{q:'Explica qué relación traza la conversación entre la mirada del niño Alfanhuí, de «Industrias y andanzas de Alfanhuí» (1951), y la teoría de la emoción de Sánchez Ferlosio.',guia:'Se espera que el lector explique que Sánchez Ferlosio describe a Alfanhuí como un niño que mira el mundo como si nadie le hubiera enseñado todavía a sentir vergüenza de mirar, es decir, sin el filtro de juicios o adjetivos que la mayoría de los narradores le ponen encima a lo que cuentan. Esa mirada limpia, según la conversación, es lo más parecido que Sánchez Ferlosio tiene a una teoría explícita de la emoción: que se gana observando con atención lo concreto, no adornando lo observado con palabras que le digan al lector qué sentir, la misma idea que sostiene la técnica objetivista de «El Jarama».',t:'Quintero y Sánchez Ferlosio'},
{q:'Explica la disputa central del careo entre la defensa y la objeción sobre hacer llorar al público, y qué es lo que las dos partes aceptan sin discutir.',guia:'Se espera que el lector explique que la defensa sostiene que conmover es el propio objetivo del relato, que el transporte narrativo (Green y Brock, 2000) funciona de verdad y que negar la emoción es una pose tan hueca como la que se ataca, mientras que la objeción sostiene que la lágrima es el efecto más barato del oficio, que el sentimentalismo es un fallo técnico (Baldwin, 1949; O\'Connor, 1969) y que el efecto de la víctima identificable (Small, Loewenstein y Slovic, 2007) se usa con frecuencia para esconder el dato en vez de abrirle camino. El terreno común que ambas aceptan es más grande de lo que parece: la emoción ganada por algo concreto es legítima y poderosa, la emoción pedida con botones es manipulación, y la línea entre una y otra no es cuánto se llora, sino si la emoción está ganada y si la historia aguanta que se vea el mecanismo que la produjo.',t:'Debate'},
{q:'Explica qué dato concreto propone el careo para acercar la disputa, y por qué ese dato resolvería mejor la cuestión que una opinión personal sobre el tema.',guia:'Se espera que el lector identifique que el careo propone estudios que comparen qué recuerda y qué hace la gente, semanas después, frente al mismo caso contado una vez con una emoción ganada por lo concreto y otra vez con una emoción pedida con un botón, y que explique por qué ese dato, y no la opinión de un crítico o una preferencia personal, resolvería mejor la disputa: porque mediría el efecto real sobre quien recibe la historia, que es justamente lo que las dos posturas dicen defender (la defensa, que la emoción ganada enseña y une más; la objeción, que la emoción de botón engaña y se olvida), en vez de quedarse en el terreno de la intuición o de lo que parece más convincente en el momento.',t:'Debate'}
];

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue distinguiendo la emoción ganada del sentimentalismo!','¡Muy buen trabajo!','¡Ya sabes cuándo una emoción se ganó su lugar!','¡El chantaje emocional ya no se te escapa!','¡Conmover, sin manipular: la cuenta te queda clara!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='💧 ¡'+name+' completó la Etapa 8 de la Ruta del Hilo que Tira (Emoción sin chantaje)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

